declarations:
interface ApiChange {
    readonly name: string;
    readonly kind: ChangeKind;
    readonly breaking: boolean;
    readonly detail: string;
}

interface ApiCheckOptions {
    readonly root: string;
    readonly update?: boolean;
    readonly readBase?: (packageName: string) => string | undefined;
    readonly allowFormatChange?: boolean;
}

interface ApiCheckResult {
    readonly problems: readonly ApiProblem[];
    readonly changes: readonly {
        readonly package: string;
        readonly changes: readonly ApiChange[];
    }[];
    readonly newPackages: readonly string[];
    readonly packagesChecked: number;
}

interface ApiExport {
    readonly name: string;
    readonly meanings: readonly Meaning[];
    readonly declarations: readonly string[];
}

interface ApiExtraction {
    readonly exports: ApiExport[];
    readonly problems: string[];
}

interface ApiProblem {
    readonly file: string;
    readonly message: string;
}

interface ApiReport {
    readonly format: number;
    readonly package: string;
    readonly version: string;
    readonly exports: readonly ApiExport[];
}

interface ImportGraphOptions {
    readonly root: string;
}

interface ImportGraphResult {
    readonly violations: readonly Violation[];
    readonly packagesChecked: number;
    readonly filesChecked: number;
}

interface ImportReference {
    readonly specifier: string;
    readonly line: number;
    readonly computed?: true;
}

interface ManifestCheckResult {
    readonly problems: readonly ManifestProblem[];
    readonly manifestsChecked: number;
}

interface ManifestInput {
    readonly file: string;
    readonly json: unknown;
    readonly register?: {
        readonly id: string;
        readonly depends: readonly string[];
    };
    readonly packageVersion?: string;
    readonly allowedLayers?: readonly Layer[];
    readonly fileExists?: (relativePath: string) => boolean;
}

interface ManifestProblem {
    readonly file: string;
    readonly message: string;
}

interface Register {
    readonly packages: readonly RegisterEntry[];
}

type RegisterParse = {
    readonly ok: true;
    readonly register: Register;
} | {
    readonly ok: false;
    readonly problems: readonly string[];
};

interface Version {
    readonly major: number;
    readonly minor: number;
    readonly patch: number;
}

interface Violation {
    readonly rule: RuleId;
    readonly message: string;
    readonly file?: string;
    readonly line?: number;
}

declare function checkManifests(options: {
    readonly root: string;
}): ManifestCheckResult;

declare function extractApi(options: {
    readonly tsconfigPath: string;
    readonly entry: string;
}): ApiExtraction;

declare const manifestSchema: z.ZodObject<{
    id: z.ZodString & z.ZodType<import("@gx/core").ModuleId, string, z.core.$ZodTypeInternals<import("@gx/core").ModuleId, string>>;
    layer: z.ZodEnum<{
        L0: "L0";
        L1: "L1";
        L2: "L2";
        L3: "L3";
        L4: "L4";
    }>;
    version: z.ZodString;
    depends: z.ZodArray<z.ZodString & z.ZodType<import("@gx/core").ModuleId, string, z.core.$ZodTypeInternals<import("@gx/core").ModuleId, string>>>;
    table_prefix: z.ZodOptional<z.ZodString>;
    entities: z.ZodArray<z.ZodString>;
    events_emitted: z.ZodArray<z.ZodObject<{
        name: z.ZodString;
        version: z.ZodNumber;
        schema: z.ZodString;
    }, z.core.$strict>>;
    events_consumed: z.ZodArray<z.ZodObject<{
        name: z.ZodString;
        version: z.ZodNumber;
    }, z.core.$strict>>;
    permissions: z.ZodArray<z.ZodString>;
    custom_field_hosts: z.ZodArray<z.ZodString>;
    workflow_hooks: z.ZodArray<z.ZodString>;
    tools: z.ZodArray<z.ZodObject<{
        name: z.ZodString;
        mode: z.ZodEnum<{
            read: "read";
            draft: "draft";
        }>;
        permission: z.ZodString;
    }, z.core.$strict>>;
    extension_points: z.ZodArray<z.ZodString>;
    config_schema: z.ZodOptional<z.ZodString>;
    errors: z.ZodRecord<z.ZodString, z.ZodObject<{
        status: z.ZodLiteral<400 | 401 | 403 | 404 | 409 | 413 | 422 | 429 | 500 | 503>;
        message: z.ZodString;
        retryable: z.ZodBoolean;
    }, z.core.$strict>>;
    tests_planned: z.ZodArray<z.ZodEnum<{
        permission: "permission";
        tenant_isolation: "tenant_isolation";
        idempotency: "idempotency";
        immutability: "immutability";
        pack_conformance: "pack_conformance";
    }>>;
}, z.core.$strict>;
